// === Tab: mySketch ===
const vert = `attribute vec3 aPosition;
  attribute vec4 aVertexColor;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec4 vVertColor;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertColor = aVertexColor;
  }
`

// This shader takes a vertex-colored mesh and replaces proper alpha blending
// with dithering
const frag = `precision mediump float;
  varying highp vec4 vVertColor;

  uniform float pixelDensity;
  uniform float seed;

  // Noise functions
  // https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
  float rand(float n) {
    return fract(sin(n) * 43758.5453123);
  }
  float rand(vec2 n) { 
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
  }
  float noise(float p) {
    float fl = floor(p);
    float fc = fract(p);
    return mix(rand(fl), rand(fl + 1.0), fc);
  }
  float noise(vec2 n) {
    const vec2 d = vec2(0.0, 1.0);
    vec2 b = floor(n);
    vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
    return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
  }

  void main() {
    float angle = seed;

    // Rotate the position (which is used to get a noise value) based on the position
    // to make the noise less repetitive
    vec2 coord = mat2(
      cos(angle), -sin(angle),
      sin(angle), cos(angle)
    ) * (gl_FragCoord.xy / pixelDensity);
    vec3 fullColor = vVertColor.xyz;

    float threshold = 1. - vVertColor.w * 1.05;

    float opacity = smoothstep(
      threshold,
      threshold + 0.05,
      fract(10. * noise(coord * 0.2) + 5. * noise(coord * 1.1))
    );

    gl_FragColor = vec4(fullColor, 1.0) * opacity;
  }
`

let img
function preload() {
  //img = loadImage('https://openprocessing.org/sketch/1450518/files/PXL_20210815_112009439.jpg')
	img = loadImage('https://openprocessing.org/sketch/1450518/files/IMG_0944.JPG');
}

let noiseGradient

function setup() {
  createCanvas(1112, 834, WEBGL)
  pixelDensity(2)
  setAttributes({ antialias: true })

  noiseGradient = createShader(vert, frag)
	img.loadPixels()
}

function gradientStroke(w, h, colors) {
	noiseGradient.setUniform('seed', random() * 1000)
  const numPoints = max(2, colors.length)
  beginShape(TRIANGLE_STRIP)
  for (let i = 0; i < numPoints; i++) {
    const y = map(i, 0, numPoints - 1, -h / 2, h / 2)
    fill(colors[min(i, colors.length - 1)])
    vertex(-w / 2, y)
    vertex(w / 2, y)
  }
  endShape()
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

function draw() {
	background(50)
	push()
	translate(-width/2, -height/2)

  noStroke()
  shader(noiseGradient)
  noiseGradient.setUniform('pixelDensity', pixelDensity())

  drawingContext.disable(drawingContext.DEPTH_TEST)
  drawingContext.enable(drawingContext.BLEND)
  drawingContext.blendFunc(drawingContext.ONE, drawingContext.ONE_MINUS_SRC_ALPHA)

	const numStrokes = 500
  for (let i = 0; i < numStrokes; i++) {
		const z = pow(random(), 6) //pow(1 - i / (numStrokes-1), 6)
		const h = map(z, 0, 1, 200, 1100) * random(0.9, 1.1)
		const w = map(z, 0, 1, 30, 80)
		const x = random(width)
		var y = (0.4 + z * 0.3 + random(-0.2, 0.2)) * height

		const pixelX = round(map(x, 0, width, 0, img.width-1, true))
		const fromPixelY = round(map(y - h/2, 0, height, 0, img.height-1, true))
		const toPixelY = round(map(y + h/2, 0, height, 0, img.height-1, true))

		const alpha = constrain(map(z, 0, 1, 255, 50) * random(0.9, 1.1), 0, 255)
		const colors = [
			color(
				img.pixels[4 * (img.width * fromPixelY + pixelX)],
				img.pixels[4 * (img.width * fromPixelY + pixelX) + 1],
				img.pixels[4 * (img.width * fromPixelY + pixelX) + 2],
				0
			),
			color(
				img.pixels[4 * (img.width * fromPixelY + pixelX)],
				img.pixels[4 * (img.width * fromPixelY + pixelX) + 1],
				img.pixels[4 * (img.width * fromPixelY + pixelX) + 2],
				alpha
			),
			color(
				img.pixels[4 * (img.width * toPixelY + pixelX)],
				img.pixels[4 * (img.width * toPixelY + pixelX) + 1],
				img.pixels[4 * (img.width * toPixelY + pixelX) + 2],
				alpha
			),
			color(
				img.pixels[4 * (img.width * toPixelY + pixelX)],
				img.pixels[4 * (img.width * toPixelY + pixelX) + 1],
				img.pixels[4 * (img.width * toPixelY + pixelX) + 2],
				0
			),
		]

		push()
		translate(x, y)
		gradientStroke(w, h, colors)
		pop()
	}
	pop()
	frameRate(1 / 2)
}

